def fahrenheit(celsius):
    return celsius * 9 / 5 + 32

def test_freezing():
    temperature = 0                      # arrange
    result = fahrenheit(temperature)     # act
    assert result == 32, f"got {result}" # assert

def test_boiling():
    assert fahrenheit(100) == 212

def test_fever():
    assert fahrenheit(36.6) == 97.88, f"got {fahrenheit(36.6)}"

def run(tests):
    failures = 0
    for test in tests:
        try:
            test()
            print("pass", test.__name__)
        except AssertionError as error:
            failures += 1
            print("FAIL", test.__name__, "-", error)
    print(failures, "failed")

run([test_freezing, test_boiling, test_fever])

