def make_basket():
    return {"apples": 2, "pears": 0}

def add(basket, item, count):
    basket[item] = basket.get(item, 0) + count

def test_add_new_item():
    basket = make_basket()
    add(basket, "figs", 3)
    assert basket["figs"] == 3

def test_starts_without_figs():
    basket = make_basket()
    assert "figs" not in basket

CASES = [
    ("apples", 1, 3),
    ("pears", 5, 5),
    ("figs", 0, 0),
]

def test_add_cases():
    failures = []
    for item, count, expected in CASES:
        basket = make_basket()
        add(basket, item, count)
        if basket[item] != expected:
            failures.append((item, count, basket[item]))
    assert not failures, failures

for test in [test_add_new_item, test_starts_without_figs, test_add_cases]:
    test()
    print(test.__name__, "passed")

