import sys

def grade(score):
    if score >= 70:
        return "distinction"
    if score >= 40:
        return "pass"
    return "fail"

def lines_run(func, argument):
    seen = set()
    first = func.__code__.co_firstlineno
    def tracer(frame, event, arg):
        if frame.f_code is func.__code__ and event == "line":
            seen.add(frame.f_lineno - first)
        return tracer
    sys.settrace(tracer)
    try:
        func(argument)
    finally:
        sys.settrace(None)
    return seen

def test_grade_runs():
    grade(90)
    grade(50)
    grade(10)

covered = set()
for score in [90, 50, 10]:
    covered = covered | lines_run(grade, score)
print("body lines of grade that ran:", sorted(covered), "of 5")

def grade(score):
    return "pass"

test_grade_runs()
print("grade is now broken, and the test still passes")

