def to_minutes(text):
    if not text:
        raise ValueError("empty duration")
    total = 0
    digits = ""
    for ch in text:
        if ch.isdigit():
            digits += ch
        elif ch in "hm" and digits:
            total += int(digits) * (60 if ch == "h" else 1)
            digits = ""
        else:
            raise ValueError("unexpected " + repr(ch) + " in " + repr(text))
    if digits:
        raise ValueError("number with no unit in " + repr(text))
    return total

