def encode(text):
    if not text:
        return ""
    parts = []
    current = text[0]
    count = 0
    for ch in text:
        if ch == current:
            count += 1
        else:
            parts.append(current + str(count))
            current = ch
            count = 1
    parts.append(current + str(count))
    return "".join(parts)

